// Extractor: tech101 (jobs) -- single-page HTML card listing.
// Generated by scripts/batch/templates/html-cards-listing.js.
// Card selector: a.career-item.group
// Hand-verify before commit; re-run \`pulchowk-events verify tech101\` after edit.
//
// Site shape: all jobs appear as cards on one listing page.
// Card selector was derived from the wizard dump's cardCandidates[0]
// (highest-scoring jobish group that isn't a section wrapper).
//
// If this returns 0 items on a site whose dump showed job cards:
//   - selector drifted (site class names changed)
//   - site structure changed (cards nested differently)
//   -> run \`pulchowk-events diagnose tech101\` or \`pulchowk-events fix tech101\`

const { delay } = require('../../page');
const { safeDiscovered, safeUnitDone } = require('../../progress');
const { detectPageState } = require('../../diagnostics');
const { sanitizeJobFields } = require('../../jobs');

const LISTING_URL = "https://tech101.com.np/vacancies";
const CARD_SELECTOR = "a.career-item.group";

module.exports = {
    async extract(page, { progress, meta }) {
        console.log('🕷️ [tech101] Scraping listing...');
        meta.pagesVisited++;
        await page.goto(LISTING_URL, { waitUntil: 'domcontentloaded', timeout: 60000 });
        await delay(1500 + Math.random() * 1000);

        // Block check before doing any DOM work.
        try {
            const state = await detectPageState(page);
            if (state.looksBlocked) {
                meta.looksBlocked = true;
                return { items: [], meta };
            }
        } catch (e) { /* best-effort */ }

        // Cards usually appear within 2-3s on sites that render them at
        // all. 5s is enough headroom for slow hydration; 15s (the previous
        // value) meant 3+ broken-template sites burned 10 extra seconds
        // each in this dead wait during a batch run.
        try {
            await page.waitForSelector(CARD_SELECTOR, { timeout: 5000 });
        } catch (e) {
            console.warn('  [tech101] card selector did not appear within 5s');
        }
        await delay(800);

        const result = await page.evaluate((cardSelector) => {
            const cards = Array.from(document.querySelectorAll(cardSelector));
            const rejected = [];

            const kept = cards.map((card, idx) => {
                // --- title ---
                let title = null;
                const heading = card.querySelector('h1, h2, h3, h4, h5, h6');
                if (heading) {
                    title = heading.textContent.trim().replace(/\\s+/g, ' ');
                } else {
                    // Fallback: a <strong> element with substantial text.
                    const strong = Array.from(card.querySelectorAll('strong, b'))
                        .find((s) => (s.textContent || '').trim().length >= 8);
                    if (strong) title = strong.textContent.trim().replace(/\\s+/g, ' ');
                }
                if (!title || title.length < 3 || title.length > 250) {
                    rejected.push({ idx, title: title || '(empty)', reason: 'title_length' });
                    return null;
                }

                // Job-title vocabulary gate, word-boundary + positional.
                // Two failure modes to avoid, both observed:
                //  - "Supportive Team" matched 'support' as a substring of
                //    "Supportive" -- not a role word when word-bounded.
                //  - "Marketing Workflow Automation with Journey Builder"
                //    matched 'marketing' mid-phrase -- the title is a
                //    product name, not a job.
                //
                // Rule:
                //  1. Strip trailing parenthetical modifiers ("(Remote)",
                //     "(Intern)", "(f/m/d)").
                //  2. If a STRONG role word appears anywhere as a
                //     word-bounded token -> accept. Strong = unambiguous
                //     noun-form role names ("Developer", "Engineer").
                //  3. Else if last word contains a BROAD role word -> accept.
                //     "Marketing Lead", "Sales Manager".
                //  4. Else if first word contains BROAD AND total words <= 3
                //     -> accept. "Marketing Lead" (already caught by rule 3),
                //     but also "Lead Engineer".
                //  5. Else reject.
                const STRONG_ROLE_WORDS = [
                    'developer', 'engineer', 'designer', 'manager', 'analyst',
                    'architect', 'intern', 'internship', 'consultant',
                    'specialist', 'officer', 'executive', 'coordinator',
                    'administrator', 'representative', 'programmer',
                    'scientist', 'researcher', 'accountant', 'recruiter',
                    'supervisor', 'technician', 'trainee', 'apprentice',
                    'clerk', 'advisor', 'strategist', 'devops', 'sre',
                    'cto', 'ceo', 'cfo', 'director', 'associate', 'assistant',
                    'linguist', 'secretary', 'librarian'
                ];
                const BROAD_ROLE_WORDS = [
                    'lead', 'head', 'sales', 'marketing', 'support',
                    'operations', 'qa', 'tester', 'writer', 'editor',
                    'artist', 'illustrator', 'producer', 'principal',
                    'partner', 'rep'
                ];
                // Token-based word matching instead of \b-regex. Avoids all
                // escaping pitfalls and handles hyphenation / punctuation
                // naturally: "Frontend Developer" -> ["frontend", "developer"].
                // A role word matches only if the token IS the role word
                // (not a substring), so "Supportive" no longer matches "support".
                const tokenize = (s) => s.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
                const containsWord = (tokenList, w) => {
                    const wTokens = tokenize(w);
                    for (let i = 0; i <= tokenList.length - wTokens.length; i++) {
                        let ok = true;
                        for (let j = 0; j < wTokens.length; j++) {
                            if (tokenList[i + j] !== wTokens[j]) { ok = false; break; }
                        }
                        if (ok) return true;
                    }
                    return false;
                };

                // Strip trailing parens/brackets: "Frontend Developer (Intern)"
                // -> "Frontend Developer". The paren content usually is a
                // seniority/format modifier, not the role noun.
                const cleanTitle = title.replace(/\s*[\[(][^\])]*[\])]\s*$/, '').trim();
                const titleLower = cleanTitle.toLowerCase();
                const words = cleanTitle.split(/\s+/).filter(Boolean);

                const titleTokens = tokenize(titleLower);
                let looksLikeJobTitle = false;
                for (const w of STRONG_ROLE_WORDS) {
                    if (containsWord(titleTokens, w)) { looksLikeJobTitle = true; break; }
                }
                if (!looksLikeJobTitle && titleTokens.length > 0) {
                    const lastToken = titleTokens[titleTokens.length - 1];
                    const firstToken = titleTokens[0];
                    for (const w of BROAD_ROLE_WORDS) {
                        if (containsWord([lastToken], w)) { looksLikeJobTitle = true; break; }
                        if (titleTokens.length <= 3 && containsWord([firstToken], w)) { looksLikeJobTitle = true; break; }
                    }
                }
                if (!looksLikeJobTitle) {
                    rejected.push({ idx, title, reason: 'no_role_word' });
                    return null;
                }

                // Reject obvious person names: two or three Title-Case words
                // with no role vocabulary. "Resham Bhandari" is a person,
                // not a job. Already excluded role-vocab names above.
                const wordCount = title.split(/\s+/).filter(Boolean).length;
                const titleCaseWords = title.split(/\s+/).filter((w) => /^[A-Z][a-z]+$/.test(w)).length;
                if (wordCount <= 3 && titleCaseWords === wordCount && title.length < 40) {
                    rejected.push({ idx, title, reason: 'person_name' });
                    return null;
                }

                // Reject pure-date titles (vianet's "2026-11-22").
                if (/^\d{4}[-\/]\d{1,2}[-\/]\d{1,2}$/.test(title)) {
                    rejected.push({ idx, title, reason: 'pure_date' });
                    return null;
                }

                // Reject sentences (end with period, >15 words).
                if (/\.$/.test(title) && wordCount > 15) {
                    rejected.push({ idx, title, reason: 'sentence' });
                    return null;
                }

                // --- link ---
                let detailUrl = null;
                const linkEl = card.tagName === 'A' ? card : card.querySelector('a[href]');
                if (linkEl) {
                    const href = linkEl.getAttribute('href');
                    if (href && !href.startsWith('#') && !href.startsWith('javascript:') && !href.startsWith('mailto:')) {
                        try { detailUrl = new URL(href, window.location.origin).href; } catch (e) { /* ignore */ }
                    }
                }

                // --- image ---
                let image = null;
                const imgEl = card.querySelector('img');
                if (imgEl) {
                    try {
                        image = typeof window.__resolveImageSrc === 'function'
                            ? window.__resolveImageSrc(imgEl)
                            : (imgEl.currentSrc || imgEl.src || null);
                    } catch (e) { image = null; }
                }

                // --- description ---
                // Prefer first <p>; fall back to innerText minus title.
                let description = '';
                const p = card.querySelector('p');
                if (p) {
                    description = (p.textContent || '').trim();
                } else {
                    const fullText = (card.innerText || '').trim();
                    description = title ? fullText.replace(title, '').trim() : fullText;
                }
                description = description.replace(/\\s+/g, ' ').slice(0, 1500);

                // --- heuristic field extraction from card text ---
                const cardText = (card.innerText || '').toLowerCase();
                let attendanceMode = 'in-person';
                if (/\\bremote\\b/.test(cardText)) attendanceMode = 'remote';
                else if (/\\bhybrid\\b/.test(cardText)) attendanceMode = 'hybrid';

                let employmentType = null;
                const typeMatch = cardText.match(/\\b(full[- ]time|part[- ]time|contract|internship|freelance|temporary)\\b/i);
                if (typeMatch) employmentType = typeMatch[1].replace(/\\s+/g, ' ');

                let location = null;
                const locMatch = cardText.match(/(?:location|based in|office):\\s*([^.\\n]{2,60})/i);
                if (locMatch) location = locMatch[1].trim();

                return { title, detailUrl, image, description, attendanceMode, employmentType, location, idx };
            }).filter(Boolean);

            return {
                totalCards: cards.length,
                items: kept,
                rejected: rejected.slice(0, 10)
            };
        }, CARD_SELECTOR);

        // listingHits = TOTAL cards matched by selector, not post-filter.
        // classifyOutcome needs the pre-filter count to distinguish "site
        // has 0 cards" (genuinely empty or drifted) from "site has N cards
        // but filter rejected all of them" (wrong group / filter too strict).
        meta.listingHits = result.totalCards;
        meta.totalCards = result.totalCards;
        meta.keptItems = result.items.length;
        meta.sampleRejected = result.rejected;
        safeDiscovered(progress, result.totalCards);

        if (result.totalCards === 0) {
            console.warn('  [tech101] card selector matched 0 elements -- site may have no jobs OR selector drifted');
            return { items: [], meta };
        }

        if (result.items.length === 0) {
            console.warn('  [tech101] matched ' + result.totalCards + ' cards but filter rejected all');
            console.warn('  [tech101] sample rejects: ' + JSON.stringify(result.rejected.slice(0, 3)));
            return { items: [], meta };
        }

        const raw = result.items;

        const items = [];
        for (const r of raw) {
            try {
                const item = {
                    id: 'html-listing-tech101-' + Date.now() + '-' + r.idx,
                    title: r.title,
                    company: "tech101",
                    companyUrl: LISTING_URL,
                    companyLogoUrl: null,
                    location: r.location,
                    employmentType: r.employmentType,
                    attendanceMode: r.attendanceMode,
                    salary: null,
                    experience: null,
                    level: null,
                    openings: null,
                    description: r.description,
                    responsibilities: '',
                    requirements: '',
                    skills: [],
                    companyDescription: '',
                    companyLocation: null,
                    companyAddress: null,
                    applicationEndsRaw: null,
                    applicationEndsDate: null,
                    daysLeftAtListTime: null,
                    url: r.detailUrl || LISTING_URL,
                    registrationUrl: r.detailUrl || LISTING_URL,
                    source: "tech101",
                    scrapedAt: Date.now()
                };
                sanitizeJobFields(item);
                if (item.title) {
                    items.push(item);
                } else {
                    meta.detailParseFailures++;
                }
            } catch (e) {
                meta.detailParseFailures++;
                console.warn('  [tech101] item parse failed: ' + e.message);
            } finally {
                safeUnitDone(progress);
            }
        }

        console.log('  [tech101] extracted ' + items.length + '/' + raw.length + ' jobs');
        return { items, meta };
    }
};
